SELECT 'core-2026-09-v4','dependent-prepositions','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"dependent-prepositions","title":"Adjectives and verbs with dependent prepositions","level":"B1","order":38,"summary":"Learn prepositions as part of a phrase, and use the right complement after them.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Learn complete combinations","Prepositions take noun-like complements","Questions can leave the preposition at the end","Keep the preposition in relative clauses"],"rules":[{"title":"Learn complete combinations","explanation":"An adjective or verb often selects a particular preposition: interested in, responsible for, depend on. These are lexical patterns rather than meanings predictable from spatial in/on/at alone. Record the phrase with a short example and its intended sense.","pattern":"**interested in** music / **depend on** support","commonMistakes":["Some words allow different prepositions with different meanings; angry with a person and angry about an event are both possible."],"examples":["“The team is interested **in** preparing the visitor guide.”","“The team is responsible **for** restoring the old portrait.”"],"skill":"form"},{"title":"Prepositions take noun-like complements","explanation":"After a preposition, use a noun, object pronoun or -ing clause when naming an action. To can itself be a preposition in expressions such as look forward to, where it is followed by -ing rather than a base verb.","pattern":"look forward to **meeting** you","commonMistakes":["Do not treat every to as an infinitive marker. Its job depends on the preceding expression."],"examples":["“The team is interested in **preparing** the visitor guide.”","“The team is responsible for **restoring** the old portrait.”"],"skill":"meaning"},{"title":"Questions can leave the preposition at the end","explanation":"A neutral direct question commonly leaves a dependent preposition near the end of its clause. Formal English can place it before whom or which, but this changes register and is not always natural with every multi-word expression.","pattern":"What are you **interested in**?","commonMistakes":["Ending an English sentence with a preposition is often entirely grammatical."],"examples":["Ask about the activity of preparing the visitor guide: “What is the team interested **in**?”","Ask about the activity of restoring the old portrait: “What is the team responsible **for**?”"],"skill":"contrast"},{"title":"Keep the preposition in relative clauses","explanation":"When a relative clause contains a dependent combination, preserve the preposition even if an object relative pronoun is omitted. A formal fronted preposition requires whom or which, not that.","pattern":"the subject **(that) she is interested in**","commonMistakes":["The subject which she is interested omits the preposition required by interested in."],"examples":["Complete the relative clause about preparing the visitor guide: “This is the activity that the team is interested **in**.”","Complete the relative clause about restoring the old portrait: “This is the activity that the team is responsible **for**.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Learn prepositions as part of a phrase, and use the right complement after them.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Learn complete combinations","explanation":"An adjective or verb often selects a particular preposition: interested in, responsible for, depend on. These are lexical patterns rather than meanings predictable from spatial in/on/at alone. Record the phrase with a short example and its intended sense.","pattern":"**interested in** music / **depend on** support","commonMistakes":["Some words allow different prepositions with different meanings; angry with a person and angry about an event are both possible."],"examples":["“The team is interested **in** preparing the visitor guide.”","“The team is responsible **for** restoring the old portrait.”"],"skill":"form","id":"dependent-prepositions-foundation-1","domain":"prepositions","referenceIds":["bc-dependent-prepositions"],"readingVersion":"core-2026-09-v3"},{"title":"Prepositions take noun-like complements","explanation":"After a preposition, use a noun, object pronoun or -ing clause when naming an action. To can itself be a preposition in expressions such as look forward to, where it is followed by -ing rather than a base verb.","pattern":"look forward to **meeting** you","commonMistakes":["Do not treat every to as an infinitive marker. Its job depends on the preceding expression."],"examples":["“The team is interested in **preparing** the visitor guide.”","“The team is responsible for **restoring** the old portrait.”"],"skill":"meaning","id":"dependent-prepositions-foundation-2","domain":"prepositions","referenceIds":["bc-dependent-prepositions"],"readingVersion":"core-2026-09-v3"},{"title":"Questions can leave the preposition at the end","explanation":"A neutral direct question commonly leaves a dependent preposition near the end of its clause. Formal English can place it before whom or which, but this changes register and is not always natural with every multi-word expression.","pattern":"What are you **interested in**?","commonMistakes":["Ending an English sentence with a preposition is often entirely grammatical."],"examples":["Ask about the activity of preparing the visitor guide: “What is the team interested **in**?”","Ask about the activity of restoring the old portrait: “What is the team responsible **for**?”"],"skill":"contrast","id":"dependent-prepositions-foundation-3","domain":"prepositions","referenceIds":["bc-dependent-prepositions"],"readingVersion":"core-2026-09-v3"},{"title":"Keep the preposition in relative clauses","explanation":"When a relative clause contains a dependent combination, preserve the preposition even if an object relative pronoun is omitted. A formal fronted preposition requires whom or which, not that.","pattern":"the subject **(that) she is interested in**","commonMistakes":["The subject which she is interested omits the preposition required by interested in."],"examples":["Complete the relative clause about preparing the visitor guide: “This is the activity that the team is interested **in**.”","Complete the relative clause about restoring the old portrait: “This is the activity that the team is responsible **for**.”"],"skill":"application","id":"dependent-prepositions-foundation-4","domain":"prepositions","referenceIds":["bc-dependent-prepositions"],"readingVersion":"core-2026-09-v3"},{"domain":"prepositions","id":"stranding-and-fronting","title":"Preposition stranding and formal fronting","explanation":"A preposition can remain at the end of a question or relative clause when its complement is understood from an earlier expression. In more formal constructions, it may move before whom or which. Both are established standard patterns. The verb and preposition combination can restrict which alternative sounds natural.","pattern":"Who did you speak **to**? / **To whom** did you speak?","examples":["That is the person **I worked with**.","That is the person **with whom I worked**."],"commonMistakes":["Ending a clause with a preposition is not inherently wrong. Avoid changing a natural standard sentence solely to satisfy that mistaken blanket prohibition."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**interested in** music / **depend on** support","look forward to **meeting** you","What are you **interested in**?","the subject **(that) she is interested in**"],"readingVersion":"core-2026-09-v4"},"stage":"4 · Connecting meanings","prerequisites":["verb-patterns"],"readingReferenceIds":["bc-dependent-prepositions","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='dependent-prepositions'
